package org.jlinalg.study;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** Exact-sequence protein context, supplied/retrieved models and explicit configured prediction. */
public final class StudyProteinPolicy {
    private StudyProteinPolicy() { }
    public static Map<String,Object> resolve(Map<String,Object> supplied){var p=new LinkedHashMap<String,Object>(supplied);
        for(String key:p.keySet())if(!Set.of("enabled","manifest","sequences","taxon_id","scope","fdr","retrieve","require_exact_sequence","require_plddt","require_pae","max_targets","max_queries","max_models_per_target","max_residues","max_file_bytes","max_pae_cells","max_region_pairs","plot_max_residues","prediction").contains(key))throw new IllegalArgumentException("Unknown protein_structure field: "+key);
        p.putIfAbsent("enabled",true);p.putIfAbsent("scope",p.containsKey("manifest")?"explicit":"primary_significant");p.putIfAbsent("fdr",.05);p.putIfAbsent("retrieve",true);p.putIfAbsent("require_exact_sequence",true);p.putIfAbsent("require_plddt",false);p.putIfAbsent("require_pae",false);p.putIfAbsent("max_targets",100);p.putIfAbsent("max_queries",500);p.putIfAbsent("max_models_per_target",20);p.putIfAbsent("max_residues",5000);p.putIfAbsent("max_file_bytes",33554432);p.putIfAbsent("max_pae_cells",4000000);p.putIfAbsent("max_region_pairs",10000);p.putIfAbsent("plot_max_residues",300);
        for(String key:List.of("enabled","retrieve","require_exact_sequence","require_plddt","require_pae"))if(!(p.get(key) instanceof Boolean))throw new IllegalArgumentException("protein_structure."+key+" must be boolean");
        if(!Set.of("explicit","primary_significant","all_primary").contains(p.get("scope")))throw new IllegalArgumentException("Invalid protein_structure.scope");
        if(!(p.get("fdr") instanceof Number fdr)||!Double.isFinite(fdr.doubleValue())||fdr.doubleValue()<=0||fdr.doubleValue()>1)throw new IllegalArgumentException("protein_structure.fdr must lie in (0,1]");
        for(String key:List.of("manifest","sequences"))if(p.containsKey(key)&&(!(p.get(key) instanceof String s)||s.isBlank()))throw new IllegalArgumentException("protein_structure."+key+" must be nonblank text");
        integer(p,"max_targets",1,10000);integer(p,"max_queries",1,100000);integer(p,"max_models_per_target",1,100);integer(p,"max_residues",1,10000);integer(p,"max_file_bytes",1024,67108864);integer(p,"max_pae_cells",1,9000000);integer(p,"max_region_pairs",1,100000);integer(p,"plot_max_residues",10,500);
        var prediction=StudyIO.optionalMap(p.get("prediction"),"protein_structure.prediction");for(String key:prediction.keySet())if(!Set.of("enabled","command","software","software_version","model_version","seeds","msa_provenance","template_provenance","timeout_seconds","output_manifest","execution_note","maximum_output_bytes","maximum_output_files","input_files","network").contains(key))throw new IllegalArgumentException("Unknown protein prediction field: "+key);prediction.putIfAbsent("enabled",false);prediction.putIfAbsent("timeout_seconds",3600);prediction.putIfAbsent("maximum_output_bytes",268435456);prediction.putIfAbsent("maximum_output_files",2000);prediction.putIfAbsent("output_manifest","prediction-outputs.yaml");prediction.putIfAbsent("network","offline");if(!Set.of("offline","online").contains(prediction.get("network")))throw new IllegalArgumentException("prediction.network must be offline or online; this records the configured program intent, not OS network isolation");
        if(prediction.containsKey("input_files")){var files=StudyIO.list(prediction.get("input_files"),"prediction.input_files");if(files.size()>1000||files.stream().anyMatch(v->!(v instanceof String s)||s.isBlank()))throw new IllegalArgumentException("Prediction input_files must be a bounded list of local file paths");}
        if(!(prediction.get("enabled") instanceof Boolean))throw new IllegalArgumentException("prediction.enabled must be boolean");integer(prediction,"timeout_seconds",1,604800);integer(prediction,"maximum_output_bytes",1024,1073741824);integer(prediction,"maximum_output_files",1,10000);if(p.containsKey("taxon_id"))integer(p,"taxon_id",1,Integer.MAX_VALUE);
        if(Boolean.TRUE.equals(prediction.get("enabled"))){var command=StudyIO.list(prediction.get("command"),"prediction.command");if(command.isEmpty()||command.size()>100||command.stream().anyMatch(v->!(v instanceof String s)||s.isBlank()))throw new IllegalArgumentException("Prediction needs a nonempty argument-vector command");for(String key:List.of("software","software_version","model_version","msa_provenance","template_provenance","output_manifest"))if(!(prediction.get(key) instanceof String s)||s.isBlank())throw new IllegalArgumentException("Configured prediction requires "+key);var seeds=StudyIO.list(prediction.get("seeds"),"prediction.seeds");if(seeds.isEmpty()||seeds.size()>100||seeds.stream().anyMatch(v->!(v instanceof Number n)||!Double.isFinite(n.doubleValue())||n.doubleValue()!=n.longValue()))throw new IllegalArgumentException("Prediction requires 1..100 integer seeds");}
        p.put("prediction",prediction);return p;
    }
    private static void integer(Map<String,Object> p,String key,int min,int max){if(!(p.get(key) instanceof Number n)||!Double.isFinite(n.doubleValue())||n.doubleValue()!=n.intValue()||n.intValue()<min||n.intValue()>max)throw new IllegalArgumentException(key+" outside integer bounds");}
}
